	const highBn = `${toBengaliNumber(weather.daily[0]?.tempMax ?? weather.currentTemp + 3)}°C`;
	const lowBn = `${toBengaliNumber(weather.daily[0]?.tempMin ?? weather.currentTemp - 4)}°C`;
